package com.banktooltips;

import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.Color;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.FocusChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

@Slf4j
@PluginDescriptor(
	name = "Bank Count Tooltips",
	description = "Shows how many of the hovered item you have in your inventory and bank",
	tags = {"bank", "tooltip", "count", "item", "hover", "bagnon"}
)
public class BankTooltipsPlugin extends Plugin
{
	private static final String SNAPSHOT_KEY = "bankSnapshot";
	private static final Type SNAPSHOT_TYPE = new TypeToken<Map<Integer, Integer>>() {}.getType();
	private static final Color LABEL_COLOR = new Color(238, 238, 238);
	private static final Color VALUE_COLOR = Color.WHITE;

	private static final Set<Integer> ITEM_INTERFACES = ImmutableSet.of(
		InterfaceID.INVENTORY,
		InterfaceID.BANKMAIN,
		InterfaceID.BANKSIDE,
		InterfaceID.BANK_DEPOSITBOX,
		InterfaceID.WORNITEMS,
		InterfaceID.SEED_VAULT,
		InterfaceID.SEED_VAULT_DEPOSIT,
		InterfaceID.LUMBRIDGE_ALCHEMY,
		InterfaceID.POH_COSTUMES_SIDE,
		InterfaceID.GE_OFFERS,
		InterfaceID.GE_OFFERS_SIDE,
		InterfaceID.GE_COLLECT,
		InterfaceID.GE_HISTORY,
		InterfaceID.GE_PRICECHECKER,
		InterfaceID.GE_PRICECHECKER_SIDE,
		InterfaceID.TRADEMAIN,
		InterfaceID.TRADESIDE,
		InterfaceID.SHOPMAIN,
		InterfaceID.SHOPSIDE
	);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private TooltipManager tooltipManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BankTooltipsOverlay overlay;

	@Inject
	private Gson gson;

	@Inject
	private BankTooltipsConfig config;

	private final StringBuilder tooltipBuilder = new StringBuilder();

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.hotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			hotkeyHeld = true;
			clientThread.invokeLater(BankTooltipsPlugin.this::refreshGeExamine);
		}

		@Override
		public void hotkeyReleased()
		{
			hotkeyHeld = false;
			clientThread.invokeLater(BankTooltipsPlugin.this::refreshGeExamine);
		}
	};

	// written on the AWT event thread, read on the client thread
	private volatile boolean hotkeyHeld;

	// remaining state is only touched on the client thread
	private Map<Integer, Integer> bankSnapshot = Collections.emptyMap();
	private boolean snapshotKnown;
	private boolean depositBoxOpen;
	private Map<Integer, Integer> depositBaseline;
	private List<String> excludedPatterns = Collections.emptyList();
	private String geExamineBase;
	private int geExamineItem = -1;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		keyManager.registerKeyListener(hotkeyListener);
		excludedPatterns = Text.fromCSV(config.excludedItems());
		clientThread.invokeLater(this::loadSnapshot);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		keyManager.unregisterKeyListener(hotkeyListener);
		hotkeyHeld = false;
		bankSnapshot = Collections.emptyMap();
		snapshotKnown = false;
		depositBoxOpen = false;
		depositBaseline = null;

		final String base = geExamineBase;
		geExamineBase = null;
		geExamineItem = -1;
		if (base != null)
		{
			clientThread.invoke(() ->
			{
				final Widget desc = client.getWidget(InterfaceID.GeOffers.SETUP_DESC);
				if (desc != null && !desc.isHidden())
				{
					desc.setText(base);
				}
			});
		}
	}

	@Provides
	BankTooltipsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankTooltipsConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BankTooltipsConfig.GROUP.equals(event.getGroup()))
		{
			excludedPatterns = Text.fromCSV(config.excludedItems());
			clientThread.invokeLater(this::refreshGeExamine);
		}
	}

	@Subscribe
	public void onFocusChanged(FocusChanged event)
	{
		if (!event.isFocused())
		{
			hotkeyHeld = false;
			clientThread.invokeLater(this::refreshGeExamine);
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadSnapshot();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANK_DEPOSITBOX)
		{
			depositBoxOpen = true;
			depositBaseline = countHeldItems();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANK_DEPOSITBOX)
		{
			depositBoxOpen = false;
			depositBaseline = null;
		}
		else if (event.getGroupId() == InterfaceID.GE_OFFERS)
		{
			geExamineBase = null;
			geExamineItem = -1;
		}
	}

	// The GE offer-setup examine panel is set once by a client script when the
	// item populates the offer; RuneLite exposes it through these callbacks.
	// Priority below the core Grand Exchange plugin's, which overwrites the text
	// outright, so capturing here keeps its buy-limit/price additions in the base.
	@Subscribe(priority = -1)
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		final String eventName = event.getEventName();
		if (!"geBuyExamineText".equals(eventName) && !"geSellExamineText".equals(eventName))
		{
			return;
		}

		final int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (itemId <= 0)
		{
			return;
		}

		final Object[] stack = client.getObjectStack();
		final int sz = client.getObjectStackSize();
		geExamineBase = (String) stack[sz - 1];
		geExamineItem = itemManager.canonicalize(itemId);
		stack[sz - 1] = geExamineText();
	}

	// panel text is static, so the hotkey is applied by rewriting the widget text
	private void refreshGeExamine()
	{
		if (geExamineBase == null)
		{
			return;
		}

		final Widget desc = client.getWidget(InterfaceID.GeOffers.SETUP_DESC);
		if (desc != null && !desc.isHidden())
		{
			desc.setText(geExamineText());
		}
	}

	private String geExamineText()
	{
		if ((config.hotkeyOnly() && !hotkeyHeld) || isExcluded(geExamineItem))
		{
			return geExamineBase;
		}

		// no color tags: the panel supplies its own text color
		final String line = buildTooltipText(geExamineItem, false);
		return line == null ? geExamineBase : geExamineBase + "<br>" + line;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		final int containerId = event.getContainerId();
		if (containerId == InventoryID.BANK)
		{
			rebuildSnapshot(event.getItemContainer());
		}
		else if (depositBoxOpen && (containerId == InventoryID.INV || containerId == InventoryID.WORN))
		{
			trackDeposits();
		}
	}

	void addHoverTooltip()
	{
		if (client.isMenuOpen() || (config.hotkeyOnly() && !hotkeyHeld))
		{
			return;
		}

		final MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
		if (menuEntries.length == 0)
		{
			return;
		}

		final MenuEntry menuEntry = menuEntries[menuEntries.length - 1];
		if (!isItemAction(menuEntry))
		{
			return;
		}

		final Widget widget = menuEntry.getWidget();
		if (widget == null)
		{
			return;
		}

		final int itemId = widgetItemId(widget);
		if (itemId <= 0)
		{
			return;
		}

		final int canonicalId = itemManager.canonicalize(itemId);
		if (canonicalId == ItemID.BANK_FILLER || isExcluded(canonicalId))
		{
			return;
		}

		final String text = buildTooltipText(canonicalId, true);
		if (text == null)
		{
			return;
		}

		final List<Tooltip> tooltips = tooltipManager.getTooltips();
		final int position = config.tooltipPosition();
		final TooltipPlacement placement = config.tooltipPlacement();

		if (placement != TooltipPlacement.OWN_BOX && !tooltips.isEmpty())
		{
			final Tooltip target = tooltips.get(positionToIndex(position, tooltips.size() - 1));
			// component-based tooltips have no text to merge into
			if (target.getText() != null)
			{
				target.setText(placement == TooltipPlacement.INSIDE_TOP
					// </col> so the host tooltip's first line keeps its own color
					? text + "</col></br>" + target.getText()
					: target.getText() + "</br>" + text);
				return;
			}
		}

		tooltips.add(positionToIndex(position, tooltips.size()), new Tooltip(text));
	}

	// equipment slots keep their item on a child widget, not the slot itself
	private static int widgetItemId(Widget widget)
	{
		final int itemId = widget.getItemId();
		if (itemId > 0 || WidgetUtil.componentToInterface(widget.getId()) != InterfaceID.WORNITEMS)
		{
			return itemId;
		}

		final Widget child = widget.getChild(1);
		return child != null ? child.getItemId() : -1;
	}

	// 1..n from the front, negatives from the end, 0 = last. maxIndex is the
	// list size when inserting, size - 1 when targeting an existing tooltip.
	private static int positionToIndex(int position, int maxIndex)
	{
		if (position > 0)
		{
			return Math.min(position - 1, maxIndex);
		}
		return Math.max(0, maxIndex + position);
	}

	private boolean isItemAction(MenuEntry menuEntry)
	{
		switch (menuEntry.getType())
		{
			case WIDGET_TARGET_ON_WIDGET:
			case WIDGET_USE_ON_ITEM:
			{
				final Widget widget = menuEntry.getWidget();
				return widget != null && widget.getId() == InterfaceID.Inventory.ITEMS;
			}
			case CC_OP:
			case ITEM_USE:
			case ITEM_FIRST_OPTION:
			case ITEM_SECOND_OPTION:
			case ITEM_THIRD_OPTION:
			case ITEM_FOURTH_OPTION:
			case ITEM_FIFTH_OPTION:
			case WIDGET_TARGET:
				return ITEM_INTERFACES.contains(WidgetUtil.componentToInterface(menuEntry.getParam1()));
			default:
				return false;
		}
	}

	private boolean isExcluded(int canonicalId)
	{
		if (excludedPatterns.isEmpty())
		{
			return false;
		}

		final String name = itemManager.getItemComposition(canonicalId).getName();
		for (String pattern : excludedPatterns)
		{
			if (WildcardMatcher.matches(pattern, name))
			{
				return true;
			}
		}
		return false;
	}

	private String buildTooltipText(int canonicalId, boolean colored)
	{
		// stackable items already show their quantity on the inventory stack
		final boolean showInv = config.showInventoryCount()
			&& (!config.hideStackableInvCount() || !itemManager.getItemComposition(canonicalId).isStackable());
		final boolean showBank = config.showBankCount();
		if (!showInv && !showBank)
		{
			return null;
		}

		final long invCount = showInv ? countInventory(canonicalId) : 0;
		final long bankCount = showBank ? bankSnapshot.getOrDefault(canonicalId, 0) : 0;

		final boolean includeInv = showInv && (invCount > 0 || !config.hideZeroCounts());
		final boolean includeBank = showBank && (bankCount > 0 || !config.hideZeroCounts());
		if (!includeInv && !includeBank)
		{
			return null;
		}

		if (includeInv)
		{
			appendSegment(config.inventoryLabel(), invCount, colored);
		}
		if (includeBank)
		{
			if (includeInv)
			{
				final String separator = config.separator().trim();
				if (colored)
				{
					tooltipBuilder.append(ColorUtil.colorTag(LABEL_COLOR));
				}
				tooltipBuilder.append(separator.isEmpty() ? " " : " " + separator + " ");
			}
			appendSegment(config.bankLabel(), bankCount, colored);
		}

		final String text = tooltipBuilder.toString();
		tooltipBuilder.setLength(0);
		return text;
	}

	private void appendSegment(String label, long count, boolean colored)
	{
		final String trimmedLabel = label.trim();
		if (!trimmedLabel.isEmpty())
		{
			if (colored)
			{
				tooltipBuilder.append(ColorUtil.colorTag(LABEL_COLOR));
			}
			tooltipBuilder.append(trimmedLabel).append(' ');
		}
		if (colored)
		{
			tooltipBuilder.append(ColorUtil.colorTag(VALUE_COLOR));
		}
		tooltipBuilder.append(formatCount(count));
	}

	private long countInventory(int canonicalId)
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return 0;
		}

		long total = 0;
		for (Item item : inventory.getItems())
		{
			// canonicalize so noted stacks count toward the base item
			if (item.getId() != -1 && itemManager.canonicalize(item.getId()) == canonicalId)
			{
				total += item.getQuantity();
			}
		}
		return total;
	}

	private String formatCount(long count)
	{
		return config.exactNumbers()
			? QuantityFormatter.formatNumber(count)
			: QuantityFormatter.quantityToStackSize(count);
	}

	private void rebuildSnapshot(ItemContainer bank)
	{
		final Map<Integer, Integer> snapshot = new HashMap<>();
		for (Item item : bank.getItems())
		{
			final int id = item.getId();
			// skip empty slots, bank fillers, and placeholders
			if (id == -1 || id == ItemID.BANK_FILLER || item.getQuantity() <= 0
				|| itemManager.canonicalize(id) != id)
			{
				continue;
			}
			snapshot.merge(id, item.getQuantity(), Integer::sum);
		}

		bankSnapshot = snapshot;
		snapshotKnown = true;
		saveSnapshot();
	}

	// The bank container isn't sent to the client while a deposit box is
	// open, so infer deposits from what leaves the inventory and equipment
	private void trackDeposits()
	{
		final Map<Integer, Integer> held = countHeldItems();
		final Map<Integer, Integer> previous = depositBaseline;
		depositBaseline = held;

		// without a snapshot to add to, deposits would look like the full bank count
		if (previous == null || !snapshotKnown)
		{
			return;
		}

		boolean changed = false;
		for (Map.Entry<Integer, Integer> entry : previous.entrySet())
		{
			final int deposited = entry.getValue() - held.getOrDefault(entry.getKey(), 0);
			if (deposited > 0)
			{
				if (!changed)
				{
					bankSnapshot = new HashMap<>(bankSnapshot);
					changed = true;
				}
				bankSnapshot.merge(entry.getKey(), deposited, Integer::sum);
			}
		}

		if (changed)
		{
			saveSnapshot();
		}
	}

	// inventory and equipment counted together so equipping items mid-deposit
	// isn't mistaken for a deposit
	private Map<Integer, Integer> countHeldItems()
	{
		final Map<Integer, Integer> counts = new HashMap<>();
		for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			final ItemContainer container = client.getItemContainer(containerId);
			if (container == null)
			{
				continue;
			}
			for (Item item : container.getItems())
			{
				if (item.getId() != -1)
				{
					counts.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
				}
			}
		}
		return counts;
	}

	private void saveSnapshot()
	{
		configManager.setRSProfileConfiguration(BankTooltipsConfig.GROUP, SNAPSHOT_KEY, gson.toJson(bankSnapshot));
	}

	private void loadSnapshot()
	{
		Map<Integer, Integer> snapshot = null;
		final String json = configManager.getRSProfileConfiguration(BankTooltipsConfig.GROUP, SNAPSHOT_KEY);
		if (json != null)
		{
			try
			{
				snapshot = gson.fromJson(json, SNAPSHOT_TYPE);
			}
			catch (JsonSyntaxException ex)
			{
				log.warn("Discarding unreadable bank snapshot", ex);
			}
		}
		bankSnapshot = snapshot != null ? snapshot : Collections.emptyMap();
		snapshotKnown = snapshot != null;
	}
}

package com.banktooltips;

import lombok.AllArgsConstructor;

@AllArgsConstructor
public enum TooltipPlacement
{
	OWN_BOX("Own box"),
	INSIDE_TOP("Inside, at top"),
	INSIDE_BOTTOM("Inside, at bottom");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.banktooltips;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;

@ConfigGroup(BankTooltipsConfig.GROUP)
public interface BankTooltipsConfig extends Config
{
	String GROUP = "banktooltips";

	@ConfigSection(
		name = "Display",
		description = "What to show in the tooltip",
		position = 0
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Hotkey",
		description = "Show the tooltip only while a hotkey is held",
		position = 1
	)
	String hotkeySection = "hotkey";

	@ConfigSection(
		name = "Labels",
		description = "Customize the tooltip text",
		position = 2
	)
	String labelsSection = "labels";

	@ConfigSection(
		name = "Filtering",
		description = "Exclude items from the tooltip",
		position = 3
	)
	String filteringSection = "filtering";

	@ConfigItem(
		keyName = "showInventoryCount",
		name = "Show inventory count",
		description = "Include the number of the hovered item held in your inventory",
		position = 1,
		section = displaySection
	)
	default boolean showInventoryCount()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideStackableInvCount",
		name = "Hide inv count for stackables",
		description = "Skip the inventory count for stackable items such as runes, whose inventory stack already shows its quantity. Noted items still count toward their base item",
		position = 2,
		section = displaySection
	)
	default boolean hideStackableInvCount()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBankCount",
		name = "Show bank count",
		description = "Include the number of the hovered item stored in your bank",
		position = 3,
		section = displaySection
	)
	default boolean showBankCount()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideZeroCounts",
		name = "Hide zero counts",
		description = "Omit a count when it is 0. If both counts are 0, no tooltip is shown",
		position = 4,
		section = displaySection
	)
	default boolean hideZeroCounts()
	{
		return true;
	}

	@ConfigItem(
		keyName = "exactNumbers",
		name = "Exact numbers",
		description = "Show exact quantities (12,450) instead of abbreviated stack sizes (12.4K)",
		position = 5,
		section = displaySection
	)
	default boolean exactNumbers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tooltipPosition",
		name = "Tooltip position",
		description = "Where this tooltip appears among the others: 0 = last, 1 = first, 2 = second, and so on. Negative counts from the end, e.g. -1 = second to last. With an 'Inside' placement, this selects which tooltip to merge into",
		position = 6,
		section = displaySection
	)
	default int tooltipPosition()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "tooltipPlacement",
		name = "Placement",
		description = "Show as a separate tooltip box, or merge into the tooltip selected by 'Tooltip position' (above or below its content)",
		position = 7,
		section = displaySection
	)
	default TooltipPlacement tooltipPlacement()
	{
		return TooltipPlacement.OWN_BOX;
	}

	@ConfigItem(
		keyName = "hotkeyOnly",
		name = "Show only while hotkey held",
		description = "Only show the tooltip while the hotkey is held down",
		position = 1,
		section = hotkeySection
	)
	default boolean hotkeyOnly()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hotkey",
		name = "Hotkey",
		description = "The key to hold to show the tooltip",
		position = 2,
		section = hotkeySection
	)
	default Keybind hotkey()
	{
		return Keybind.CTRL;
	}

	@ConfigItem(
		keyName = "inventoryLabel",
		name = "Inventory label",
		description = "Label shown before the inventory count, e.g. 'Inv:', 'I:' or 'Inventory:'. Leave empty for no label",
		position = 1,
		section = labelsSection
	)
	default String inventoryLabel()
	{
		return "Inv:";
	}

	@ConfigItem(
		keyName = "bankLabel",
		name = "Bank label",
		description = "Label shown before the bank count, e.g. 'Bank:' or 'B:'. Leave empty for no label",
		position = 2,
		section = labelsSection
	)
	default String bankLabel()
	{
		return "Bank:";
	}

	@ConfigItem(
		keyName = "separator",
		name = "Separator",
		description = "Text between the inventory and bank counts. Leave empty for a single space",
		position = 3,
		section = labelsSection
	)
	default String separator()
	{
		return "|";
	}

	@ConfigItem(
		keyName = "excludedItems",
		name = "Excluded items",
		description = "Comma-separated list of item names to never show the tooltip for. Supports wildcards, e.g. 'Coins, *rune, Shark'",
		position = 1,
		section = filteringSection
	)
	default String excludedItems()
	{
		return "";
	}
}

package com.banktooltips;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Renders nothing; runs after other tooltip-producing overlays but before
 * TooltipOverlay, so the tooltip list is complete when ours is inserted.
 */
class BankTooltipsOverlay extends Overlay
{
	private final BankTooltipsPlugin plugin;

	@Inject
	BankTooltipsOverlay(BankTooltipsPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		plugin.addHoverTooltip();
		return null;
	}
}
